package com.cgs.atvobserver

import com.cgs.atvobserver.data.db.AppDatabase
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Host test: the Room schema generated by KSP for this app is the original v5 schema.
 * The identity hash is what Room stores in room_master_table; equality means an in-place update
 * over v1.1.6/v1.1.7 opens the existing database without migration or data loss.
 */
class RoomSchemaIdentityTest {
    private val schema = File("schemas/com.cgs.atvobserver.data.db.AppDatabase/5.json").readText()

    @Test fun identityHashMatchesOriginalV5() {
        assertEquals(AppDatabase.IDENTITY_HASH_V5, Regex("\"identityHash\": \"([0-9a-f]+)\"").find(schema)!!.groupValues[1])
        assertEquals("c0123e4383c0dbb3474efce306556582", AppDatabase.IDENTITY_HASH_V5)
        assertEquals(5, AppDatabase.VERSION)
    }

    @Test fun createStatementsMatchOriginalAppDatabaseImpl() {
        // verbatim from reference/jadx/atvobserver/data/db/AppDatabase_Impl.java (with Room's ${TABLE_NAME} placeholder)
        val rideLogs = "CREATE TABLE IF NOT EXISTS `\${TABLE_NAME}` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `startTime` INTEGER NOT NULL, `midTime` INTEGER NOT NULL, `endTime` INTEGER NOT NULL, `durationSeconds` INTEGER NOT NULL, `distanceKm` REAL NOT NULL, `maxSpeedKmh` REAL NOT NULL, `avgSpeedKmh` REAL NOT NULL, `estimatedFuelUsedL` REAL NOT NULL, `weatherCondition` TEXT NOT NULL, `mode` TEXT NOT NULL, `vehicleType` TEXT NOT NULL, `warningCount` INTEGER NOT NULL, `isFinished` INTEGER NOT NULL, `startLat` REAL NOT NULL, `startLon` REAL NOT NULL, `midLat` REAL NOT NULL, `midLon` REAL NOT NULL, `endLat` REAL NOT NULL, `endLon` REAL NOT NULL, `peakGForce` REAL NOT NULL, `smoothnessScore` INTEGER NOT NULL, `launchAccelTimeSec` REAL NOT NULL, `terrainSummary` TEXT NOT NULL, `isCompressed` INTEGER NOT NULL)"
        val fuel = "CREATE TABLE IF NOT EXISTS `\${TABLE_NAME}` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `fuelLitres` REAL NOT NULL, `entryType` TEXT NOT NULL, `vehicleType` TEXT NOT NULL)"
        val cal = "CREATE TABLE IF NOT EXISTS `\${TABLE_NAME}` (`key` TEXT NOT NULL, `value` TEXT NOT NULL, `confidence` TEXT NOT NULL, `lastUpdated` INTEGER NOT NULL, PRIMARY KEY(`key`))"
        val unescaped = schema.replace("\\\"", "\"")
        for (s in listOf(rideLogs, fuel, cal)) assertTrue("missing: $s", unescaped.contains(s))
    }

    @Test fun noDestructiveFallbackInSource() {
        val src = File("src/main/java/com/cgs/atvobserver/data/db/AppDatabase.kt").readText()
        assertFalse(src.contains("fallbackToDestructiveMigration("))
    }
}
